-- Haradon loot
-- Generated by NetCoreClient/tools/M425Patch from the 425 tables. Do not edit; re-run tools/build-m425.sh.
SET NAMES utf8mb4;

DELETE FROM `creature_loot_template` WHERE `entry` BETWEEN 900000 AND 999999;
DELETE FROM `gameobject_loot_template` WHERE `entry` BETWEEN 900000 AND 999999;
DELETE FROM `item_loot_template` WHERE `entry` BETWEEN 100000 AND 199999;

DELETE l FROM `item_loot_template` l JOIN `item_template` t ON t.`entry` = l.`entry` WHERE l.`entry` BETWEEN 100000 AND 199999 AND t.`inventory_type` <> 0;
UPDATE `gameobject_template` t SET t.`data1` = 0 WHERE t.`entry` BETWEEN 900000 AND 999999 AND t.`type` = 3 AND NOT EXISTS (SELECT 1 FROM `gameobject_loot_template` l WHERE l.`entry` = t.`data1`);
UPDATE `creature_template` t SET t.`loot_id` = t.`entry` WHERE t.`entry` BETWEEN 900000 AND 999999 AND EXISTS (SELECT 1 FROM `creature_loot_template` l WHERE l.`entry` = t.`entry`);
UPDATE `item_template` t SET t.`flags` = t.`flags` | 4 WHERE t.`entry` BETWEEN 100000 AND 199999 AND EXISTS (SELECT 1 FROM `item_loot_template` l WHERE l.`entry` = t.`entry`);
